def slugify(text: str) -> str:
    if not isinstance(text, str):
        return ""

    words = []
    current = []

    for ch in text:
        if ch.isalpha() or ch.isdigit():
            current.append(ch)
        elif current:
            words.append("".join(current).lower())
            current = []

    if current:
        words.append("".join(current).lower())

    if not words:
        return ""

    result = "-".join(words)

    if len(result) <= 60:
        return result

    if len(words[0]) > 60:
        return result[:60]

    length = len(words[0])
    last_word = 0

    for i in range(1, len(words)):
        candidate_length = length + 1 + len(words[i])
        if candidate_length > 60:
            break
        length = candidate_length
        last_word = i

    return "-".join(words[:last_word + 1])
