from __future__ import annotations


def parse_csv_line(line: str) -> list[str]:
    if line.startswith("\ufeff"):
        line = line[1:]

    if line == "":
        return []

    fields: list[str] = []
    n = len(line)
    i = 0

    while True:
        if i < n and line[i] == '"':
            # Поле в кавычках.
            i += 1
            chars: list[str] = []

            while True:
                if i >= n:
                    raise ValueError("unclosed quoted field")

                ch = line[i]

                if ch == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        # Удвоенная кавычка внутри quoted-поля.
                        chars.append('"')
                        i += 2
                    else:
                        # Закрывающая кавычка.
                        i += 1
                        if i < n and line[i] != ",":
                            raise ValueError(
                                "unexpected character after closing quote"
                            )
                        break
                else:
                    chars.append(ch)
                    i += 1

            fields.append("".join(chars))

            if i == n:
                break

            # line[i] == ','
            i += 1
            if i == n:
                fields.append("")
                break

        else:
            # Незакавыченное поле: пробелы и прочие символы сохраняются.
            start = i
            while i < n and line[i] != ",":
                i += 1

            fields.append(line[start:i])

            if i == n:
                break

            # line[i] == ','
            i += 1
            if i == n:
                fields.append("")
                break

    return fields

