import threading
import time
from typing import Any, Dict


class RateLimiter:
    _EPS = 1e-9

    def __init__(self, rate: int, per_seconds: float, clock=None):
        if rate <= 0:
            raise ValueError("rate must be positive")
        if per_seconds <= 0:
            raise ValueError("per_seconds must be positive")

        self._capacity = rate
        self._refill_per_second = rate / per_seconds
        self._clock = clock if clock is not None else time.monotonic

        self._buckets: Dict[Any, list] = {}
        self._lock = threading.Lock()

    def _validate_cost(self, cost: int) -> None:
        if isinstance(cost, bool) or not isinstance(cost, int) or cost <= 0:
            raise ValueError("cost must be a positive integer")
        if cost > self._capacity:
            raise ValueError("cost must not exceed capacity")

    def _get_tokens_locked(self, key: Any, now: float) -> float:
        bucket = self._buckets.get(key)

        if bucket is None:
            tokens = float(self._capacity)
            self._buckets[key] = [tokens, now]
            return tokens

        tokens, last_time = bucket

        if now > last_time:
            tokens += (now - last_time) * self._refill_per_second
            if tokens > self._capacity:
                tokens = float(self._capacity)
            bucket[0] = tokens
            bucket[1] = now

        return tokens

    def allow(self, key: Any, cost: int = 1) -> bool:
        self._validate_cost(cost)

        with self._lock:
            now = self._clock()
            tokens = self._get_tokens_locked(key, now)

            if tokens + self._EPS >= cost:
                tokens -= cost
                if tokens < 0:
                    tokens = 0.0
                self._buckets[key][0] = tokens
                return True

            return False

    def state(self, key: Any) -> dict:
        with self._lock:
            now = self._clock()
            tokens = self._get_tokens_locked(key, now)
            return {
                "tokens": round(tokens, 3),
                "capacity": self._capacity,
            }

    def reset(self, key: Any) -> None:
        with self._lock:
            now = self._clock()
            self._buckets[key] = [float(self._capacity), now]
